feasible=[c for c in candidates if c['report']['reference_min']>0 and c['report']['all_fields_correct']/c['report']['validation_tokens']>=.995];chosen=min(feasible,key=lambda c:c['report']['word_raw_change_rms']) if feasible else None;out={'native_cancellation':best,'native_cancellation_trials':fits,'lexical_coefficients':coeff,'lexical_bias':bias,'lexical_mapping_report':mapping['report'],'candidates':candidates,'trials':trials,'chosen':chosen,'field_names':['reference']+lex['fields'],'support_selection':'ascending native post-MLP0 variance times frozen readout column energy','memory_covariance':'native post-MLP0 word covariance plus100 times unpredictable numeric pre-MLP0 covariance'};torch.save(out,ROOT/'artifacts/r_sparse_memory_v1.pt');(ROOT/'artifacts/r_sparse_memory_v1.json').write_text(json.dumps({'chosen':None if chosen is None else chosen['report'],'native_cancellation_trials':fits,'trials':trials},indent=2)+'\n');print('chosen',json.dumps(None if chosen is None else chosen['report']),flush=True)
